import os
import firebase_admin


def get_config():
    return {
        "project_id": os.getenv('FIREBASE_PROJECT_ID')
    }


def initialize_firebase_app(config):
    try:
        app = firebase_admin.get_app()
    except ValueError:
        app = firebase_admin.initialize_app(options={"projectId": config["project_id"]})
    return app

class IdentityRequest:
    def __init__(self, email, password):
        self.email = email
        self.password = password


class IdentityResponse:
    def __init__(self, user_id):
        self.user_id = user_id


def normalize_response(response):
    return IdentityResponse(response["user_id"])

import re


def moderate_profile_text(text):
    if re.search(r'\b(hate|violence|discrimination)\b', text, re.IGNORECASE):
        raise ValueError('Profile text contains inappropriate content.')
    return text

import os
import boto3


def store_profile_note(user_id, note):
    client = boto3.client('dynamodb', region_name='us-west-2', aws_access_key_id=os.getenv('AWS_ACCESS_KEY_ID'), aws_secret_access_key=os.getenv('AWS_SECRET_ACCESS_KEY'))
    client.put_item(
        TableName='OnboardingNotes',
        Item={
            'user_id': {'S': user_id},
            'note': {'S': note}
        }
    )
